import booking


def test_cancellation_fee_at_least_24_hours_returns_integer_zero():
    for hours in (24, 48):
        result = booking.cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

import booking


def test_cancellation_fee_from_zero_through_23_returns_integer_2500():
    for hours in (0, 23):
        result = booking.cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 2500

import pytest
import booking


def test_non_builtin_int_arguments_raise_type_error():
    for hours in (True, 1.0, "1"):
        with pytest.raises(TypeError):
            booking.cancellation_fee(hours)
